package com.capybee.engine.generation.blueprint.json;

import com.capybee.engine.generation.blueprint.ParsedGameBlueprint;
import com.capybee.engine.generation.blueprint.ParsedGameBlueprint.*;
import java.util.*;
import tools.jackson.databind.json.JsonMapper;

/** Deterministic proposal-format writer. It performs no filesystem I/O. */
public final class BlueprintWriter {
    private static final JsonMapper JSON=JsonMapper.builder().build();
    public byte[] write(ParsedGameBlueprint b){Objects.requireNonNull(b);return JSON.writeValueAsBytes(root(b));}
    public String writeString(ParsedGameBlueprint b){return new String(write(b),java.nio.charset.StandardCharsets.UTF_8);}
    private static Map<String,Object> root(ParsedGameBlueprint b){return map("schemaVersion",b.schemaVersion(),"locale",b.locale(),"title",b.title(),"premise",b.premise(),"setting",b.setting(),"toneTags",b.toneTags(),"storyPromises",b.storyPromises(),"actors",b.actors().stream().map(x->map("id",x.id(),"name",x.name(),"role",x.role(),"description",x.description())).toList(),"state",state(b.state()),"objectives",b.objectives().stream().map(x->map("id",x.id(),"title",x.title(),"description",x.description(),"completeWhen",condition(x.completeWhen()))).toList(),"phases",b.phases().stream().map(x->map("kind",x.kind().name(),"goal",x.goal(),"development",x.development(),"transition",x.transition(),"actorIds",x.actorIds(),"objectiveIds",x.objectiveIds())).toList(),"startSceneId",b.startSceneId(),"scenes",b.scenes().stream().map(BlueprintWriter::scene).toList(),"outcomes",b.outcomes().stream().map(x->map("id",x.id(),"resultClass",x.resultClass().name(),"title",x.title(),"description",x.description())).toList());}
    private static Object state(State s){return map("counters",s.counters().stream().map(x->map("id",x.id(),"min",x.min(),"max",x.max(),"initial",x.initial())).toList(),"flags",s.flags().stream().map(x->map("id",x.id(),"initial",x.initial())).toList(),"sets",s.sets().stream().map(x->map("id",x.id(),"values",x.values(),"initial",x.initial())).toList());}
    private static Object scene(Scene value){if(value instanceof DecisionScene x)return map("id",x.id(),"kind","DECISION","phase",x.phase().name(),"title",x.title(),"intent",x.intent(),"actorIds",x.actorIds(),"objectiveIds",x.objectiveIds(),"choices",x.choices().stream().map(c->map("id",c.id(),"intent",c.intent(),"destinationSceneId",c.destinationSceneId(),"requires",c.requires()==null?null:condition(c.requires()),"effects",c.effects().stream().map(BlueprintWriter::effect).toList())).toList());EndingScene x=(EndingScene)value;return map("id",x.id(),"kind","ENDING","phase",x.phase().name(),"title",x.title(),"intent",x.intent(),"actorIds",x.actorIds(),"objectiveIds",x.objectiveIds(),"outcomeId",x.outcomeId());}
    private static Object condition(Condition value){if(value instanceof CounterCondition x)return map("type",x.type(),"counter",x.counter(),"value",x.value());if(value instanceof FlagCondition x)return map("type","FLAG_IS","flag",x.flag(),"value",x.value());if(value instanceof SetContainsCondition x)return map("type","SET_CONTAINS","set",x.set(),"value",x.value());if(value instanceof SetSizeCondition x)return map("type","SET_SIZE_AT_LEAST","set",x.set(),"size",x.size());if(value instanceof VisitedSceneCondition x)return map("type","VISITED_SCENE","scene",x.scene());if(value instanceof CompositeCondition x)return map("type",x.type(),"conditions",x.conditions().stream().map(BlueprintWriter::condition).toList());return map("type","NOT","condition",condition(((NotCondition)value).condition()));}
    private static Object effect(Effect value){if(value instanceof CounterEffect x)return x.type().equals("COUNTER_ADD")?map("type",x.type(),"counter",x.counter(),"delta",x.value()):map("type",x.type(),"counter",x.counter(),"value",x.value());if(value instanceof FlagEffect x)return map("type","FLAG_SET","flag",x.flag(),"value",x.value());SetEffect x=(SetEffect)value;return map("type",x.type(),"set",x.set(),"value",x.value());}
    private static Map<String,Object> map(Object... pairs){Map<String,Object> result=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)result.put((String)pairs[i],pairs[i+1]);return result;}
}
